class Solution:
    def maximumScore(self, scores: List[int], edges: List[List[int]]) -> int:
        n = len(scores)
        adj = [[] for _ in range(n)]
        for a, b in edges:
            adj[a].append(b)
            adj[b].append(a)
        ans = -1
        for a, b in edges:
            for c in adj[a]:
                if c == b:
                    continue
                for d in adj[b]:
                    if d == a or d == b or d == c:
                        continue
                    ans = max(ans, scores[a] + scores[b] + scores[c] + scores[d])
        return ans

