class Solution {
public:
    int maximumScore(vector<int>& scores, vector<vector<int>>& edges) {
        int n = scores.size();
        vector<vector<pair<int,int>>> top(n);
        for (auto& e : edges) {
            top[e[0]].push_back({scores[e[1]], e[1]});
            top[e[1]].push_back({scores[e[0]], e[0]});
        }
        for (auto& t : top) {
            sort(t.rbegin(), t.rend());
            if (t.size() > 3) t.resize(3);
        }
        int ans = -1;
        for (auto& e : edges) {
            int a = e[0], b = e[1];
            for (auto& [sc, c] : top[a]) {
                if (c == b) continue;
                for (auto& [sd, d] : top[b]) {
                    if (d == a || d == b || d == c) continue;
                    ans = max(ans, sc + sd + scores[a] + scores[b]);
                }
            }
        }
        return ans;
    }
};

