class Solution {
    public int maximumScore(int[] scores, int[][] edges) {
        int n = scores.length;
        List<int[]>[] top = new List[n];
        for (int i = 0; i < n; i++) top[i] = new ArrayList<>();
        for (int[] e : edges) {
            top[e[0]].add(new int[]{scores[e[1]], e[1]});
            top[e[1]].add(new int[]{scores[e[0]], e[0]});
        }
        for (List<int[]> t : top) {
            t.sort((x, y) -> y[0] - x[0]);
            while (t.size() > 3) t.remove(t.size() - 1);
        }
        int ans = -1;
        for (int[] e : edges) {
            int a = e[0], b = e[1];
            for (int[] pc : top[a]) {
                if (pc[1] == b) continue;
                for (int[] pd : top[b]) {
                    if (pd[1] == a || pd[1] == b || pd[1] == pc[1]) continue;
                    ans = Math.max(ans, pc[0] + pd[0] + scores[a] + scores[b]);
                }
            }
        }
        return ans;
    }
}

